package com.internalops.workbench;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;
@Service public class FulfillmentService{private final JdbcTemplate jdbc;private final InventoryAllocationService allocation;public FulfillmentService(JdbcTemplate j,InventoryAllocationService a){jdbc=j;allocation=a;}@Transactional public Map<String,Object> ship(long id,ShippingRequest r){String status=jdbc.queryForObject("SELECT status FROM sales_order WHERE id=? FOR UPDATE",String.class,id);if(!"READY_TO_SHIP".equals(status))throw new IllegalStateException("必须全部产品齐货后才能整单发货");if(r.trackingNo()==null||r.trackingNo().isBlank())throw new IllegalArgumentException("物流单号不能为空");long wh=Objects.requireNonNull(jdbc.queryForObject("SELECT id FROM warehouse WHERE is_default=TRUE AND enabled=TRUE ORDER BY id LIMIT 1",Long.class));for(var item:jdbc.queryForList("SELECT id,sku_id,quantity,shipped_quantity,locked_quantity FROM sales_order_item WHERE sales_order_id=?",id)){int qty=(int)InventoryAllocationService.num(item,"quantity")-(int)InventoryAllocationService.num(item,"shipped_quantity");if(qty==0)continue;if(InventoryAllocationService.num(item,"locked_quantity")!=qty)throw new IllegalStateException("必须全部产品齐货后才能整单发货");long sku=InventoryAllocationService.num(item,"sku_id");var b=jdbc.queryForMap("SELECT id,actual_quantity,locked_quantity,in_transit_quantity FROM inventory_balance WHERE warehouse_id=? AND sku_id=? FOR UPDATE",wh,sku);int a=(int)InventoryAllocationService.num(b,"actual_quantity"),l=(int)InventoryAllocationService.num(b,"locked_quantity"),t=(int)InventoryAllocationService.num(b,"in_transit_quantity");jdbc.update("UPDATE inventory_balance SET actual_quantity=actual_quantity-?,locked_quantity=locked_quantity-?,version=version+1 WHERE id=?",qty,qty,InventoryAllocationService.num(b,"id"));jdbc.update("UPDATE sales_order_item SET shipped_quantity=quantity,uncovered_quantity=0,version=version+1 WHERE id=?",InventoryAllocationService.num(item,"id"));allocation.tx(wh,sku,"SALES_SHIPMENT","SALES_ORDER",String.valueOf(id),-qty,-qty,0,a,a-qty,l,l-qty,t,t);}jdbc.update("UPDATE sales_order SET status='SHIPPED',shipped_at=?,carrier=?,tracking_no=?,shipping_remark=?,version=version+1 WHERE id=?",LocalDateTime.now(),r.carrier(),r.trackingNo(),r.shippingRemark(),id);return Map.of("id",id,"status","SHIPPED");}public record ShippingRequest(String carrier,String trackingNo,String shippingRemark){}}
